// libbufs messages in C#: the reader (Table) and builder (MessageBuilder) that code generated by `bufsc --cs` is written
// against. The format is libbufs/docs/design.md: little-endian, 8-aligned, references are forward offsets from their
// own slot, scalars are stored XOR their schema default. Reading is bounds-checked by the spans (an out-of-range
// offset throws), so a malformed message cannot read memory it does not own.
using System.Buffers.Binary;
using System.Runtime.InteropServices;
using System.Text;

namespace Bufs;

public class MalformedMessageException : Exception
{
    public MalformedMessageException(string message) : base(message) { }
}

/// <summary>A table of a message, read in place: every accessor reads the bytes it is asked about.</summary>
public readonly struct Table
{
    public const int HeaderBytes = 8;

    private readonly ReadOnlyMemory<byte> _buf;
    private readonly int _at;
    private readonly int _dataBytes;
    private readonly int _refCount;

    public Table(ReadOnlyMemory<byte> buf, int at)
    {
        _buf = buf;
        _at = at;
        var s = buf.Span;
        _dataBytes = BinaryPrimitives.ReadUInt16LittleEndian(s.Slice(at, 2));
        _refCount = BinaryPrimitives.ReadUInt16LittleEndian(s.Slice(at + 2, 2));
    }

    /// <summary>Checks the header of <paramref name="data"/> and returns its root table.</summary>
    public static Table Root(ReadOnlyMemory<byte> data, uint typeId, string typeName)
    {
        var s = data.Span;
        if (s.Length < HeaderBytes + 4) throw new MalformedMessageException($"{typeName}: message is too short");
        uint size = BinaryPrimitives.ReadUInt32LittleEndian(s);
        if (size < HeaderBytes + 4 || size > s.Length || size % 8 != 0) throw new MalformedMessageException($"{typeName}: bad message size");
        uint actual = BinaryPrimitives.ReadUInt32LittleEndian(s.Slice(4));
        if (actual != typeId) throw new MalformedMessageException($"{typeName}: wrong message type 0x{actual:x}");
        return new Table(data, HeaderBytes);
    }

    /// <summary>The size a message declares in its header (a frame may hold more).</summary>
    public static int MessageSize(ReadOnlySpan<byte> data) => data.Length >= 4 ? (int)BinaryPrimitives.ReadUInt32LittleEndian(data) : 0;

    public ReadOnlyMemory<byte> Buffer => _buf;
    private ReadOnlySpan<byte> S => _buf.Span;

    // A field past the writer's data section reads as 0, which XOR the default is the default.
    public byte U8(int off, byte d = 0) => (byte)((off + 1 <= _dataBytes ? S[_at + off] : 0) ^ d);
    public sbyte I8(int off, sbyte d = 0) => (sbyte)((off + 1 <= _dataBytes ? (sbyte)S[_at + off] : 0) ^ d);
    public ushort U16(int off, ushort d = 0) => (ushort)((off + 2 <= _dataBytes ? BinaryPrimitives.ReadUInt16LittleEndian(S.Slice(_at + off)) : 0) ^ d);
    public short I16(int off, short d = 0) => (short)((off + 2 <= _dataBytes ? BinaryPrimitives.ReadInt16LittleEndian(S.Slice(_at + off)) : 0) ^ d);
    public uint U32(int off, uint d = 0) => (off + 4 <= _dataBytes ? BinaryPrimitives.ReadUInt32LittleEndian(S.Slice(_at + off)) : 0u) ^ d;
    public int I32(int off, int d = 0) => (off + 4 <= _dataBytes ? BinaryPrimitives.ReadInt32LittleEndian(S.Slice(_at + off)) : 0) ^ d;
    public ulong U64(int off, ulong d = 0) => (off + 8 <= _dataBytes ? BinaryPrimitives.ReadUInt64LittleEndian(S.Slice(_at + off)) : 0ul) ^ d;
    public long I64(int off, long d = 0) => (off + 8 <= _dataBytes ? BinaryPrimitives.ReadInt64LittleEndian(S.Slice(_at + off)) : 0L) ^ d;
    /// <param name="dBits">the bit pattern of the default</param>
    public float F32(int off, uint dBits = 0) => BitConverter.UInt32BitsToSingle(U32(off, dBits));
    public double F64(int off, ulong dBits = 0) => BitConverter.UInt64BitsToDouble(U64(off, dBits));
    public bool Bit(int byteOffset, int bit, int d = 0) => ((((off(byteOffset)) >> bit) & 1) ^ d) == 1;
    private int off(int byteOffset) => U8(byteOffset);

    /// <summary>Absolute offset of an inline struct of <paramref name="size"/> bytes at <paramref name="off"/>, or -1.</summary>
    public int StructAt(int off, int size) => off + size <= _dataBytes ? _at + off : -1;

    /// <summary>Absolute offset the reference <paramref name="index"/> points to, or -1 when it is null or absent.</summary>
    public int Ref(int index)
    {
        if (index >= _refCount) return -1;
        int slot = _at + Align4(_dataBytes) + 4 * index;
        uint relative = BinaryPrimitives.ReadUInt32LittleEndian(S.Slice(slot));
        return relative == 0 ? -1 : slot + (int)relative;
    }

    public bool Has(int index) => Ref(index) >= 0;

    public string String(int index)
    {
        int target = Ref(index);
        return target < 0 ? "" : Encoding.UTF8.GetString(Utf8At(target));
    }

    /// <summary>The UTF-8 bytes of a string field, in place.</summary>
    public ReadOnlySpan<byte> Utf8(int index)
    {
        int target = Ref(index);
        return target < 0 ? default : Utf8At(target);
    }

    private ReadOnlySpan<byte> Utf8At(int target)
    {
        uint length = BinaryPrimitives.ReadUInt32LittleEndian(S.Slice(target));
        return S.Slice(target + 4, (int)length);
    }

    public Table? TableField(int index)
    {
        int target = Ref(index);
        return target < 0 ? null : new Table(_buf, target);
    }

    public bool Vector(int index, out int start, out int count)
    {
        int target = Ref(index);
        if (target < 0)
        {
            start = count = 0;
            return false;
        }
        start = target + 4;
        count = (int)BinaryPrimitives.ReadUInt32LittleEndian(S.Slice(target));
        return true;
    }

    /// <summary>A vector of bytes, in place.</summary>
    public ReadOnlySpan<byte> Bytes(int index)
    {
        if (!Vector(index, out int start, out int count)) return default;
        return S.Slice(start, count);
    }

    /// <summary>A vector of scalars read in place as <typeparamref name="T"/> (little-endian hosts).</summary>
    public ReadOnlySpan<T> Scalars<T>(int index) where T : unmanaged
    {
        if (!Vector(index, out int start, out int count)) return default;
        return MemoryMarshal.Cast<byte, T>(S.Slice(start, count * System.Runtime.CompilerServices.Unsafe.SizeOf<T>()));
    }

    public bool[] Bools(int index)
    {
        if (!Vector(index, out int start, out int count)) return Array.Empty<bool>();
        var result = new bool[count];
        for (int i = 0; i < count; i++) result[i] = S[start + i] != 0;
        return result;
    }

    public string[] Strings(int index)
    {
        if (!Vector(index, out int start, out int count)) return Array.Empty<string>();
        var result = new string[count];
        for (int i = 0; i < count; i++)
        {
            int slot = start + 4 * i;
            uint relative = BinaryPrimitives.ReadUInt32LittleEndian(S.Slice(slot));
            result[i] = relative == 0 ? "" : Encoding.UTF8.GetString(Utf8At(slot + (int)relative));
        }
        return result;
    }

    public Table[] Tables(int index)
    {
        if (!Vector(index, out int start, out int count)) return Array.Empty<Table>();
        var result = new Table[count];
        for (int i = 0; i < count; i++)
        {
            int slot = start + 4 * i;
            result[i] = new Table(_buf, slot + (int)BinaryPrimitives.ReadUInt32LittleEndian(S.Slice(slot)));
        }
        return result;
    }

    /// <summary>A vector of elements read with <paramref name="read"/>(span, absolute offset).</summary>
    public T[] List<T>(int index, int elementBytes, Func<ReadOnlyMemory<byte>, int, T> read)
    {
        if (!Vector(index, out int start, out int count)) return Array.Empty<T>();
        if (start + (long)count * elementBytes > _buf.Length) throw new MalformedMessageException("vector runs past the end of the message");
        var result = new T[count];
        for (int i = 0; i < count; i++) result[i] = read(_buf, start + i * elementBytes);
        return result;
    }

    internal static int Align4(int n) => (n + 3) & ~3;
}

/// <summary>
/// Builds one message front to back with the allocation rules of include/bufs/builder.hpp: tables 8-aligned, vectors
/// 4-aligned (4 mod 8 when their elements are 8 bytes), forward references, padding zeroed.
/// </summary>
public sealed class MessageBuilder
{
    private byte[] _bytes = new byte[256];
    private int _used;

    public MessageBuilder(uint typeId)
    {
        Allocate(Bufs.Table.HeaderBytes, 8, 0);
        BinaryPrimitives.WriteUInt32LittleEndian(_bytes.AsSpan(4), typeId);
    }

    /// <summary>The message so far, for writing structs in place (it changes when the buffer grows).</summary>
    public Span<byte> Span => _bytes;

    public int Allocate(int bytes, int align, int phase)
    {
        int at = _used;
        while (at % align != phase) at += 4;
        int end = Table.Align4(at + bytes);
        if (end > _bytes.Length) Array.Resize(ref _bytes, Math.Max(end, _bytes.Length * 2));
        _used = end;
        return at;
    }

    public int NewTable(int dataBytes, int refCount)
    {
        int at = Allocate(Bufs.Table.Align4(dataBytes) + 4 * refCount, 8, 0);
        BinaryPrimitives.WriteUInt16LittleEndian(_bytes.AsSpan(at), (ushort)dataBytes);
        BinaryPrimitives.WriteUInt16LittleEndian(_bytes.AsSpan(at + 2), (ushort)refCount);
        return at;
    }

    public int NewVector(int count, int elementBytes, int elementAlign)
    {
        int bytes = 4 + count * elementBytes;
        int at = elementAlign == 8 ? Allocate(bytes, 8, 4) : Allocate(bytes, 4, 0);
        BinaryPrimitives.WriteUInt32LittleEndian(_bytes.AsSpan(at), (uint)count);
        return at;
    }

    public int NewString(string text)
    {
        int length = Encoding.UTF8.GetByteCount(text);
        int at = Allocate(4 + length + 1, 4, 0);
        BinaryPrimitives.WriteUInt32LittleEndian(_bytes.AsSpan(at), (uint)length);
        Encoding.UTF8.GetBytes(text, _bytes.AsSpan(at + 4));
        return at;
    }

    public int ByteVector(ReadOnlySpan<byte> data)
    {
        int at = NewVector(data.Length, 1, 4);
        data.CopyTo(_bytes.AsSpan(at + 4));
        return at;
    }

    public void SetRef(int table, int dataBytes, int refIndex, int target)
    {
        int slot = table + Bufs.Table.Align4(dataBytes) + 4 * refIndex;
        BinaryPrimitives.WriteUInt32LittleEndian(_bytes.AsSpan(slot), (uint)(target - slot));
    }

    public void SetElementRef(int vector, int index, int target)
    {
        int slot = vector + 4 + 4 * index;
        BinaryPrimitives.WriteUInt32LittleEndian(_bytes.AsSpan(slot), (uint)(target - slot));
    }

    // Scalars are stored XOR their schema default.
    public void SetU8(int at, byte v, byte d = 0) => _bytes[at] = (byte)(v ^ d);
    public void SetI8(int at, sbyte v, sbyte d = 0) => _bytes[at] = (byte)(v ^ d);
    public void SetU16(int at, ushort v, ushort d = 0) => BinaryPrimitives.WriteUInt16LittleEndian(_bytes.AsSpan(at), (ushort)(v ^ d));
    public void SetI16(int at, short v, short d = 0) => BinaryPrimitives.WriteInt16LittleEndian(_bytes.AsSpan(at), (short)(v ^ d));
    public void SetU32(int at, uint v, uint d = 0) => BinaryPrimitives.WriteUInt32LittleEndian(_bytes.AsSpan(at), v ^ d);
    public void SetI32(int at, int v, int d = 0) => BinaryPrimitives.WriteInt32LittleEndian(_bytes.AsSpan(at), v ^ d);
    public void SetU64(int at, ulong v, ulong d = 0) => BinaryPrimitives.WriteUInt64LittleEndian(_bytes.AsSpan(at), v ^ d);
    public void SetI64(int at, long v, long d = 0) => BinaryPrimitives.WriteInt64LittleEndian(_bytes.AsSpan(at), v ^ d);
    public void SetF32(int at, float v, uint dBits = 0) => BinaryPrimitives.WriteUInt32LittleEndian(_bytes.AsSpan(at), BitConverter.SingleToUInt32Bits(v) ^ dBits);
    public void SetF64(int at, double v, ulong dBits = 0) => BinaryPrimitives.WriteUInt64LittleEndian(_bytes.AsSpan(at), BitConverter.DoubleToUInt64Bits(v) ^ dBits);
    public void SetBit(int byteAt, int bit, bool v, int d = 0)
    {
        int stored = (v ? 1 : 0) ^ d;
        _bytes[byteAt] = (byte)((_bytes[byteAt] & ~(1 << bit)) | (stored << bit));
    }

    /// <summary>Seals the message: pads to 8, writes the size, returns the bytes (a copy).</summary>
    public byte[] Finish()
    {
        int end = Allocate(0, 8, 0);
        BinaryPrimitives.WriteUInt32LittleEndian(_bytes.AsSpan(0), (uint)end);
        return _bytes.AsSpan(0, end).ToArray();
    }
}
